$path = Join-Path $PSScriptRoot '..\server\src\lifestyle-admin.js'
$content = Get-Content -LiteralPath $path -Raw
$old = "const publicItem=item=>({id:item._id.toString(),slug:item.slug,kind:item.kind||'chapter',section:item.section||'General Muslim Life',parentCategorySlug:item.parentCategorySlug||'',category:item.category,title:item.title,subtitle:item.subtitle,icon:item.icon,order:item.order,published:item.published,quran:item.quran||null,introduction:item.introduction||[],lessons:item.lessons||[],actions:item.actions||[],mistakes:item.mistakes||[],checklist:item.checklist||[],practice:item.practice||'',reflection:item.reflection||'',summary:item.summary||'',sources:item.sources||[]});"
$new = @'
const languageCode=value=>{const code=clean(value,20);return /^[a-z]{2,3}(?:-[A-Za-z]{2,8})?$/.test(code)?code:'en'};
const localizedPayload=body=>({title:clean(body.title,180),subtitle:clean(body.subtitle,300),quran:body.quran&&typeof body.quran==='object'?{surah:clean(body.quran.surah,100),reference:clean(body.quran.reference,50),arabic:clean(body.quran.arabic,1200),meaning:clean(body.quran.meaning,1600),lesson:clean(body.quran.lesson,2400),url:clean(body.quran.url,500)}:null,introduction:list(body.introduction,12,50000),lessons:list(body.lessons,20),actions:list(body.actions,20),mistakes:list(body.mistakes,20),checklist:list(body.checklist,20),practice:clean(body.practice,2400),reflection:clean(body.reflection,1200),summary:clean(body.summary,1600),sources:Array.isArray(body.sources)?body.sources.slice(0,20).map(x=>({label:clean(x?.label,160),note:clean(x?.note,800),url:clean(x?.url,500)})).filter(x=>x.label&&x.url):[]});
const publicItem=(item,language='en',adminView=false)=>{const code=languageCode(language),translation=code==='en'?null:item.translations?.[code],localized=translation||item;return{id:item._id.toString(),slug:item.slug,kind:item.kind||'chapter',section:item.section||'General Muslim Life',parentCategorySlug:item.parentCategorySlug||'',category:item.category,title:localized.title||item.title,subtitle:localized.subtitle||item.subtitle,icon:item.icon,order:item.order,published:item.published,quran:localized.quran||item.quran||null,introduction:localized.introduction?.length?localized.introduction:item.introduction||[],lessons:localized.lessons?.length?localized.lessons:item.lessons||[],actions:localized.actions?.length?localized.actions:item.actions||[],mistakes:localized.mistakes?.length?localized.mistakes:item.mistakes||[],checklist:localized.checklist?.length?localized.checklist:item.checklist||[],practice:localized.practice||item.practice||'',reflection:localized.reflection||item.reflection||'',summary:localized.summary||item.summary||'',sources:localized.sources?.length?localized.sources:item.sources||[],language:translation?code:'en',requestedLanguage:code,hasTranslation:Boolean(translation),availableLanguages:['en',...Object.keys(item.translations||{})],...(adminView?{translations:item.translations||{}}:{})}};
'@
if (-not $content.Contains($old)) { throw 'publicItem anchor not found' }
$content = $content.Replace($old,$new.Trim())
$content = $content.Replace(" r.get('/api/islamic-lifestyle',async(_req,res)=>{try{const items=await getCollection().find({published:true}).sort({section:1,parentCategorySlug:1,order:1,title:1}).toArray();res.set('Cache-Control','no-store, max-age=0');res.json({data:items.map(publicItem)})", " r.get('/api/islamic-lifestyle',async(req,res)=>{try{const language=languageCode(req.query.language),items=await getCollection().find({published:true}).sort({section:1,parentCategorySlug:1,order:1,title:1}).toArray();res.set('Cache-Control','no-store, max-age=0');res.json({data:items.map(item=>publicItem(item,language))})")
$content = $content.Replace("res.json({data:items.map(publicItem)})});`r`n r.post", "res.json({data:items.map(item=>publicItem(item,'en',true))})});`r`n r.post")
$oldPut = "const item=payload(req.body),result=await getCollection().findOneAndUpdate({_id:new ObjectId(req.params.id)},{`$set:{...item,updatedAt:new Date()}},{returnDocument:'after'});"
$newPut = "const language=languageCode(req.body.language),item=payload(req.body),updates=language==='en'?{...item,updatedAt:new Date()}:{['translations.'+language]:localizedPayload(req.body),updatedAt:new Date()},result=await getCollection().findOneAndUpdate({_id:new ObjectId(req.params.id)},{`$set:updates},{returnDocument:'after'});"
if (-not $content.Contains($oldPut)) { throw 'PUT anchor not found' }
$content = $content.Replace($oldPut,$newPut)
$content = $content.Replace("res.json({data:publicItem(result)})}catch", "res.json({data:publicItem(result,'en',true)})}catch")
[IO.File]::WriteAllText((Resolve-Path $path), $content, [Text.UTF8Encoding]::new($false))
